import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long total = 0;
        String bestNom = "";
        long bestRosi = Long.MIN_VALUE;
        while (in.hasNext()) {
            String nom = in.next();
            long sle = in.nextLong(), oldin = in.nextLong(), keyin = in.nextLong(), narx = in.nextLong();
            long aleOldin = sle * oldin / 10;
            long aleKeyin = sle * keyin / 10;
            long foyda = aleOldin - aleKeyin;
            long rosi = (foyda - narx) * 100 / narx;
            String qaror = rosi > 0 ? "implement" : "reconsider";
            total += foyda;
            if (rosi > bestRosi) {
                bestRosi = rosi;
                bestNom = nom;
            }
            System.out.println(nom + ": ALE " + aleOldin + " -> " + aleKeyin + ", benefit " + foyda + ", ROSI " + rosi + "%, " + qaror);
        }
        System.out.println("total benefit: " + total);
        System.out.println("best: " + bestNom);
    }
}

