#include <climits>
#include <iostream>
#include <string>
using namespace std;

int main() {
    string nom;
    long long sle, oldin, keyin, narx;
    long long total = 0;
    string bestNom = "";
    long long bestRosi = LLONG_MIN;
    while (cin >> nom >> sle >> oldin >> keyin >> narx) {
        long long aleOldin = sle * oldin / 10;
        long long aleKeyin = sle * keyin / 10;
        long long foyda = aleOldin - aleKeyin;
        long long rosi = (foyda - narx) * 100 / narx;
        string qaror = rosi > 0 ? "implement" : "reconsider";
        total += foyda;
        if (rosi > bestRosi) {
            bestRosi = rosi;
            bestNom = nom;
        }
        cout << nom << ": ALE " << aleOldin << " -> " << aleKeyin << ", benefit " << foyda << ", ROSI " << rosi << "%, " << qaror << "\n";
    }
    cout << "total benefit: " << total << "\n";
    cout << "best: " << bestNom << "\n";
    return 0;
}
